head.script:
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        tab_Main.setSelectedTabIndex(1);
        // debug 용 콘트롤들 모두 숨기기.
        scwin.hideDebugCtrls();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        // Grd_com_isur.style.zIndex = 30;

        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.setCode();
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33020.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MARKET_TP_CD.setValue(js_market);
    if (js_market === "9") {
        panel_mkt_gubun.hide();
    } else {
        // 콘트롤 잠그기.
        panel_mkt_gubun.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_Main_OnSelChanged
 * @description tab Main On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_Main_OnSelChanged = function(nIndex) {
    try {
        if (tab_Main.getSelectedTabIndex() === 1) {
            panel_Chb_Search.show("");
        } else {
            panel_Chb_Search.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33020.tab_Main_OnSelChanged" });
    }
};

/**
 * @method
 * @name grd_Tab1_OnDblClick
 * @description grd_Tab1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Tab1_OnDblClick = async function(row, colid) {
    try {
        scwin.setId(row);
        if (colid === 'LNK_DISCLS_SUBMIT_DDTM') {
            await $c.frame.CreateFrame("ULDSTF33021" + row, "/issueinfo/ULDSTF33021.gfm", "연계공시 신청내역", 200, 70, 950, 560 + 30, "window", 0, 0, true);
        } else if (colid === 'HDCOM_COM_ABBRV') {
            scwin.gIsurCd = dts_Tab1.getCellData(row, "HDCOM_ISUR_CD");
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === 'SUBCOM_COM_ABBRV') {
            scwin.gIsurCd = dts_Tab1.getCellData(row, "SUBCOM_ISUR_CD");
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF33020.grd_Tab1_OnDblClick" });
    }
};

