/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF33020.xml", SCREN_PROCS_TP_CD_07, '');
        if (tab_Main.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_Tab1, {fileName: "연계공시법인 현황", type: "8"});
        } else if (tab_Main.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_Tab2, {fileName: "신규상장예정 자회사 현황", type: "8"});
        } else if (tab_Main.getSelectedTabIndex() === 3) {
            $c.data.downloadGridViewExcel(grd_Tab3, {fileName: "상장폐지예정 자회사 현황", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF33020.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
