 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {

};

/**
 * @method
 * @name setId
 * @description set Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(obj) {
    g_hdcom_isur_cd = dts_Tab1.getCellData(Number(obj), "HDCOM_ISUR_CD");
    g_hdcom_com_abbrv = dts_Tab1.getCellData(Number(obj), "HDCOM_COM_ABBRV");
    g_hdcom_lm_mkt_tp_cd = dts_Tab1.getCellData(Number(obj), "HDCOM_LD_MKT_TP_NM");
};
